query:
SELECT ?item ?prop ?st ?rank ?value ?at ?atPrec ?atCal ?start ?startPrec ?startCal ?end ?endPrec ?endCal ?nature WHERE {
  VALUES ?item { wd:Q1047 wd:Q1058 wd:Q1149 wd:Q127369 wd:Q13117237 wd:Q144732 wd:Q156349 wd:Q157068 wd:Q16845347 wd:Q16858248 wd:Q197736 wd:Q19901232 wd:Q20875 wd:Q2091579 wd:Q218661 wd:Q233289 wd:Q235454 wd:Q244689 wd:Q248484 wd:Q2627138 wd:Q269412 wd:Q2724621 wd:Q275146 wd:Q280856 wd:Q297950 wd:Q312557 wd:Q315338 wd:Q317769 wd:Q317778 wd:Q319824 wd:Q3236324 wd:Q3238719 wd:Q332157 wd:Q334279 wd:Q334851 wd:Q336913 wd:Q377870 wd:Q378404 wd:Q400807 wd:Q41914 wd:Q4593 wd:Q47854 wd:Q4848887 wd:Q485547 wd:Q486188 wd:Q5228002 wd:Q544182 wd:Q544228 wd:Q555247 wd:Q557749 wd:Q558714 wd:Q559490 wd:Q57446 wd:Q590227 wd:Q6123062 wd:Q6932430 wd:Q719449 wd:Q732026 wd:Q797848 wd:Q83653 wd:Q83672 wd:Q8597 wd:Q9439 wd:Q9513 }
  VALUES (?prop ?p ?ps ?psv) { ("P569" p:P569 ps:P569 psv:P569) ("P570" p:P570 ps:P570 psv:P570) ("P53" p:P53 ps:P53 psv:P53) }
  ?item ?p ?st . ?st wikibase:rank ?rank ; ?ps ?value .
  FILTER(?rank != wikibase:DeprecatedRank)
  OPTIONAL { ?st ?psv [ wikibase:timeValue ?at ; wikibase:timePrecision ?atPrec ; wikibase:timeCalendarModel ?atCal ] . }
  OPTIONAL { ?st pqv:P580 [ wikibase:timeValue ?start ; wikibase:timePrecision ?startPrec ; wikibase:timeCalendarModel ?startCal ] . }
  OPTIONAL { ?st pqv:P582 [ wikibase:timeValue ?end ; wikibase:timePrecision ?endPrec ; wikibase:timeCalendarModel ?endCal ] . }
  OPTIONAL { ?st pq:P5102 ?nature . }
}
